triggers.trg_catalogos_modulo_actualizado:
CREATE TRIGGER `trg_catalogos_modulo_actualizado` BEFORE UPDATE ON `catalogos_modulo` FOR EACH ROW BEGIN
  SET NEW.actualizado_at = CURRENT_TIMESTAMP;
END

